using System;using System.Linq;using SynapticSea.Core.Procgen;using SynapticSea.Core.Services;using SynapticSea.Core.Variant;
static class Boundary { public static void Run(){CoreServices.Resources=new FileSystemResourceReader("F:/tmp/synaptic-sea-playable/SynapticSea/Assets/StreamingAssets");Console.WriteLine("kind,profile,biome,difficulty,size,condition,generated,standing_goal,encounters,deterministic");foreach(string p in new[]{"",ConstrainedExpedition.Profile})foreach(string biome in new[]{"abyssal_synaptic_sea","breach_field","dead_fleet"})foreach(string diff in new[]{"standard","hardened","deep_dive"})foreach(int size in new[]{1,2})foreach(int condition in new[]{0,1,2}){var gen=new ShipGenerator();gen.ConfigureRunContext(biome,diff);var bp=new ShipBlueprint(size,condition,17){GenerationProfile=p};var doc=gen.Generate(bp);var second=gen.Generate(bp);Console.WriteLine($"context,{p},{biome},{diff},{size},{condition},{doc!=null},{(doc!=null&&FirstRunAwayGate.HasStandingStartToGoal(doc.Layout))},{doc?.Layout.GetArrayOrEmpty("encounters").Count},{(doc!=null&&GdJson.Stringify(doc.ToDict())==GdJson.Stringify(second.ToDict()))}");}foreach(string p in new[]{"unknown_profile",ConstrainedExpedition.Profile,ConstrainedExpedition.LegacyProfile})foreach(int size in new[]{-1,0,1,2,3}){var gen=new ShipGenerator();var doc=gen.Generate(new ShipBlueprint(size,0,17){GenerationProfile=p});Console.WriteLine($"boundary,{p},,,{size},0,{doc!=null},,,");}foreach(int size in new[]{1,2})foreach(int seed in new[]{17,42}){var bp=new ShipBlueprint(size,0,seed){GenerationProfile=ConstrainedExpedition.Profile};var grid=ConstrainedExpedition.LayoutWithAttemptBudget(bp,0,out var plan);Console.WriteLine($"forced_fallback,{bp.GenerationProfile},,,{size},0,{!grid.IsEmpty},status={grid.GetDictOrEmpty("composition_diagnostics").GetString("status")},rooms={plan.Count},first={plan[0].GetString("role")};last={plan.Last().GetString("role")}");}}}
